def f(g):
    P=[(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==2]
    out=[row[:] for row in g]
    trunk=None
    for i in range(len(P)):
        for j in range(i+1,len(P)):
            (r1,c1),(r2,c2)=P[i],P[j]
            if r1==r2 or c1==c2: trunk=(P[i],P[j])
    (r1,c1),(r2,c2)=trunk
    cells=set()
    for r in range(min(r1,r2),max(r1,r2)+1):
        for c in range(min(c1,c2),max(c1,c2)+1): cells.add((r,c))
    for (r,c) in P:
        if (r,c) in trunk: continue
        if c1==c2:  # vertical trunk -> horizontal connector
            for cc in range(min(c,c1),max(c,c1)+1): cells.add((r,cc))
        else:
            for rr in range(min(r,r1),max(r,r1)+1): cells.add((rr,c))
    for (r,c) in cells:
        if out[r][c]==0: out[r][c]=3
    return out
